-- CA_0183_seat_current_judges_from_court_rosters.sql
-- Seat 421 CURRENT judges and justices on the offices that already exist for them, and clear is_incumbent on 79
-- judge rows the courts no longer list. Part of the "active incumbent with no office_terms row" clean-up
-- (CA_0180 - CA_0182).
--
-- WHY: 502 'manual' rows (471 "Judge, Los Angeles County Superior Court", 24 Second District Court of Appeal and
-- 7 California Supreme Court) each point, through the legacy politicians.office_id, to their own office -- and none
-- of those offices has an office_terms row. The ADR 0002 phase-2 backfill read offices.politician_id, which these
-- offices never had, so since phase 5 every one of them is INVISIBLE: no holder, and the 502 offices are 502 of the
-- 662 unflagged rows of essentials.offices_missing_terms. The rows themselves still read is_incumbent = true.
--
-- EVIDENCE (fetched 2026-09-23 from the courts' own sites):
--   * LA Superior Court judicial officer directory, https://www.lacourt.ca.gov/apps/judicial-officers/home (its
--     search API, all 554 records: 483 Judges, 71 Commissioners excluded).
--   * Second District Court of Appeal justices, https://appellate.courts.ca.gov/district-courts/2dca/justices
--     ("Assigned Judges: September 2026", 31 justices).
--   * California Supreme Court justices, https://supreme.courts.ca.gov/about-court/justices-court (6 justices and a
--     vacant seat: Justice Martin J. Jenkins retired 2025-10-31).
--
-- MATCHING (per row, by first and last name, suffixes ignored):
--   SEATED 421 -- LA Superior Court 407 (401 exact, plus 6 where the directory uses the short name: Abigail M. Baron =
--     "Abby Baron", Edwin P. Chau = "Ed Chau", Patrick Connolly = "Pat Connolly", Harry Jay Ford III = "H. Jay Ford,
--     III", C. Virginia Keeny = "Virginia Keeny", Timothy R. Saito = "Tim R. Saito"); Court of Appeal 8; Supreme
--     Court 6 (Chief Justice Patricia Guerrero and five Associate Justices).
--     Two Court of Appeal justices sit on a different office than their row pointed to, because the roster gives a
--     different title: Maria E. Stratton is now Presiding Justice of Division 8 (seated on that office, which pointed to
--     Elizabeth A. Grimes, no longer listed), and Lamar W. Baker is an Associate Justice of Division 5 (seated on the
--     Division 5 associate office that pointed to Laurence D. Moor, no longer listed).
--     Anne H. Egerton (Division 3) is listed today; her retirement on 2026-10-11 is announced but not yet happened.
--     Each term: term_start NULL, start_precision 'unknown', how_started 'unknown' -- the directory gives no start
--     date, and CLAUDE.md says to write an unknown start rather than guess one (the phase-2 backfill convention).
--     essentials.seat_officeholder() refuses a NULL start, so the rows are inserted directly; each office has no term
--     at all, so there is no predecessor to close.
--   CLEARED 79 -- not on the court's current list: LA Superior Court 62 (55 with no name match at all, among them
--     Nicholas F. Daum, Stephen I. Goorvitch, Mark K. Hanasono and Armen Tamzarian, who are now Court of Appeal
--     justices; and 7 whose surname matches only a DIFFERENT judge, e.g. Jacqueline H. Lewis vs Paris G. / Terrance T.
--     Lewis); Court of Appeal 16 (retired or moved, e.g. Lee Smalley Edmon, Audrey B. Collins, Arthur Gilbert,
--     Dennis M. Perluss; and 5 whose surname matches only a different justice); Supreme Court 1 (Martin J. Jenkins).
--     They stay active with is_incumbent = false (CA_0156 convention). Their offices stay termless: a successor may
--     hold the seat, but the courts do not map judges to these per-judge slots, so none is invented.
--   LEFT ALONE 2 -- Roy G. Delgado (the directory has "Rogelio Delgado") and Juan Carlos Dominguez (the directory has
--     "E. Carlos Dominguez"): probably the same people, but not certain from the names.
--
-- NOT IN SCOPE: the directory judges with no row here -- 76 LA Superior Court and 23 Court of Appeal (recent
-- appointees, the four judges elevated to the Court of Appeal, and seats this DB never modeled).
--
-- No migration runner exists; this file records SQL applied by hand (pure DML). No DELETE.
-- STATUS: APPLIED to prod 2026-09-23 (operator approval: Chris Andrews). Dry run x2 repeated right before the apply;
--   verified after: 421 terms written, all 421 read back through office_current_holder; offices_missing_terms 850 -> 429
--   (241 not flagged is_vacant); 79 former judges cleared. Roy G. Delgado and Juan Carlos Dominguez stay unresolved.
--
-- ROLLBACK:
--   DELETE FROM essentials.office_terms WHERE source LIKE 'CA_0183 (2026-09-23): listed as a current judge%';
--   UPDATE essentials.politicians SET is_incumbent = true, notes = array(SELECT n FROM unnest(notes) n WHERE n NOT LIKE 'CA_0183 (2026-09-23)%')
--    WHERE EXISTS (SELECT 1 FROM unnest(notes) n WHERE n LIKE 'CA_0183 (2026-09-23): not listed on%');
-- IDEMPOTENT: each insert and update is guarded on its pre-image; a re-run changes nothing and every gate still passes.

BEGIN;

CREATE TEMP TABLE _seat (politician_id uuid PRIMARY KEY, office_id uuid UNIQUE, full_name text, source text) ON COMMIT DROP;

CREATE TEMP TABLE _former (politician_id uuid PRIMARY KEY, full_name text, note text) ON COMMIT DROP;

CREATE TEMP TABLE _before ON COMMIT DROP AS
SELECT (SELECT count(*) FROM essentials.offices_missing_terms) AS missing_terms,
       (SELECT count(*) FROM essentials.office_terms) AS terms;

-- ─── Pre-flight ──────────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE v_n int;
BEGIN
  SELECT count(*) INTO v_n FROM _seat; IF v_n <> 421 THEN RAISE EXCEPTION 'PRE: _seat holds %, expected 421', v_n; END IF;
  SELECT count(*) INTO v_n FROM _former; IF v_n <> 79 THEN RAISE EXCEPTION 'PRE: _former holds %, expected 79', v_n; END IF;

  -- each judge to seat: the active 'manual' row by that name, holding no term; its office is a judicial office with no
  -- term at all (or, on a re-run, exactly this CA_0183 term)
  SELECT count(*) INTO v_n FROM _seat s
    JOIN essentials.politicians p ON p.id = s.politician_id AND p.full_name = s.full_name AND p.is_active AND p.source = 'manual'
    JOIN essentials.offices o ON o.id = s.office_id
    JOIN essentials.districts d ON d.id = o.district_id AND d.is_judicial
   WHERE (NOT EXISTS (SELECT 1 FROM essentials.office_terms t WHERE t.office_id = s.office_id)
          AND NOT EXISTS (SELECT 1 FROM essentials.office_terms t WHERE t.politician_id = s.politician_id))
      OR EXISTS (SELECT 1 FROM essentials.office_terms t WHERE t.office_id = s.office_id AND t.politician_id = s.politician_id
                   AND t.source LIKE 'CA_0183 (2026-09-23)%');
  IF v_n <> 421 THEN RAISE EXCEPTION 'PRE: % of 421 judges are termless on a termless judicial office', v_n; END IF;

  -- each former judge: the active 'manual' row by that name, holding no term
  SELECT count(*) INTO v_n FROM _former f
    JOIN essentials.politicians p ON p.id = f.politician_id AND p.full_name = f.full_name AND p.is_active AND p.source = 'manual'
   WHERE NOT EXISTS (SELECT 1 FROM essentials.office_terms t WHERE t.politician_id = f.politician_id);
  IF v_n <> 79 THEN RAISE EXCEPTION 'PRE: % of 79 former-judge rows are active and termless', v_n; END IF;

  SELECT count(*) INTO v_n FROM _seat s JOIN _former f ON f.politician_id = s.politician_id;
  IF v_n <> 0 THEN RAISE EXCEPTION 'PRE: % row(s) in both lists', v_n; END IF;
END $$;

-- ─── 1. Seat the 421 ─────────────────────────────────────────────────────────────────────────
SELECT s.office_id, s.politician_id, NULL, 'unknown', 'unknown', s.source
  FROM _seat s
 WHERE NOT EXISTS (SELECT 1 FROM essentials.office_terms t WHERE t.office_id = s.office_id);

-- ─── 2. Clear is_incumbent on the 79 ────────────────────────────────────────────────────────────
UPDATE essentials.politicians p
   SET is_incumbent = false, notes = COALESCE(p.notes, ARRAY[]::text[]) || f.note
  FROM _former f
 WHERE p.id = f.politician_id AND p.is_incumbent;

-- ─── Post-verify gate ────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE v_n int; b record;
BEGIN
  SELECT * INTO b FROM _before;

  -- every judge in _seat is now the current holder of exactly its office, and is still an active incumbent
  SELECT count(*) INTO v_n FROM _seat s
    JOIN essentials.office_current_holder och ON och.office_id = s.office_id AND och.politician_id = s.politician_id
    JOIN essentials.politicians p ON p.id = s.politician_id AND p.is_active AND p.is_incumbent;
  IF v_n <> 421 THEN RAISE EXCEPTION 'POST: % of 421 judges are the current holder of their office', v_n; END IF;
  SELECT count(*) INTO v_n FROM essentials.office_terms t JOIN _seat s ON s.politician_id = t.politician_id;
  IF v_n <> 421 THEN RAISE EXCEPTION 'POST: % terms for the 421 judges, expected exactly one each', v_n; END IF;
  SELECT count(*) INTO v_n FROM essentials.office_terms WHERE source LIKE 'CA_0183 (2026-09-23)%';
  IF v_n <> 421 THEN RAISE EXCEPTION 'POST: % CA_0183 terms, expected 421', v_n; END IF;

  -- the 79 are active, not incumbent, noted, and still hold nothing
  SELECT count(*) INTO v_n FROM _former f JOIN essentials.politicians p ON p.id = f.politician_id
   WHERE p.is_active AND NOT p.is_incumbent AND f.note = ANY (p.notes)
     AND NOT EXISTS (SELECT 1 FROM essentials.office_terms t WHERE t.politician_id = f.politician_id);
  IF v_n <> 79 THEN RAISE EXCEPTION 'POST: % of 79 former-judge rows cleared', v_n; END IF;

  -- the invisible-office count fell by exactly the terms inserted in this run (0 on a re-run)
  SELECT count(*) INTO v_n FROM essentials.offices_missing_terms;
  IF v_n <> b.missing_terms - ((SELECT count(*) FROM essentials.office_terms) - b.terms) THEN
    RAISE EXCEPTION 'POST: offices_missing_terms is %, expected % minus the % terms inserted', v_n, b.missing_terms,
      (SELECT count(*) FROM essentials.office_terms) - b.terms;
  END IF;

  RAISE NOTICE 'CA_0183 applied: 421 judges seated (offices_missing_terms % -> %), 79 former judges cleared', b.missing_terms, v_n;
END $$;

COMMIT;
